#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    while (cin >> n) {
        vector<long long> a(n);
        for (auto &x : a) cin >> x;
        long long inv = 0;
        for (int i=0;i<n;i++)
            for (int j=i+1;j<n;j++)
                if (a[i] > a[j]) inv++;
        cout << "Minimum exchange operations : " << inv << "\n";
    }
}

